<template><SettingsPageShell title="Agent 权限"><p class="page-description">权限决定 Agent 何时可以读写文件和执行命令。危险命令和路径逃逸在所有模式下都会被拦截。</p><el-radio-group v-model="config.globalDefaultMode" class="permission-options"><el-radio-button value="default"><strong>默认权限</strong><span>读取和搜索自动批准；写入和命令逐次确认。</span></el-radio-button><el-radio-button value="auto-approve"><strong>自动审核</strong><span>项目目录内读写自动批准；目录外和系统命令确认。</span></el-radio-button><el-radio-button value="full"><strong>完全访问</strong><span>不弹确认；仍保留危险命令、路径和删除硬限制。</span></el-radio-button></el-radio-group><section class="permission-settings"><h2>回收站</h2><el-form label-position="top"><el-form-item label="保留天数"><el-input-number v-model="config.trashRetentionDays" :min="1" :max="30"/></el-form-item></el-form><el-button type="primary" @click="save">保存权限设置</el-button></section></SettingsPageShell></template><script setup lang="ts">import{onMounted,reactive}from'vue';import{ElMessage}from'element-plus';import{getPlatformApi}from'@/platform';import{DEFAULT_PERMISSION_CONFIG,type PermissionConfig}from'@/config/harness';import SettingsPageShell from '../settings/components/SettingsPageShell.vue';const config=reactive<PermissionConfig>({...DEFAULT_PERMISSION_CONFIG});async function load(){Object.assign(config,await getPlatformApi()?.getHarnessPermissionConfig()||DEFAULT_PERMISSION_CONFIG)}async function save(){await getPlatformApi()?.saveHarnessPermissionConfig(config);ElMessage.success('权限设置已保存')};onMounted(load);</script><style scoped lang="scss">.page-description{margin:0 0 $spacing-xl;color:var(--cp-text-secondary);font-size:$font-sm}.permission-options{display:grid;grid-template-columns:1fr;gap:$spacing-md;width:100%}.permission-options :deep(.el-radio-button__inner){display:block;width:100%;padding:$spacing-lg;border:1px solid var(--cp-border-light)!important;border-radius:$radius-md!important;box-shadow:none!important;text-align:left}.permission-options strong,.permission-options span{display:block}.permission-options span{margin-top:6px;color:var(--cp-text-secondary);font-size:$font-sm;line-height:1.55}.permission-settings{margin-top:$spacing-xl;padding-top:$spacing-xl;border-top:1px solid var(--cp-border-light)}.permission-settings h2{font-size:$font-lg}</style>
